//   Phase 2a/2b (ConstrainedStep loops): ConstrainedStep hard-masks to
//     parser-valid tokens plus EOS. AppendConstrainedToken's postcondition
//     gives IsValidPrefix(currentConstrainedOut + [next]). EOS path breaks
//     without appending, leaving state unchanged. CloseSpanIfComplete either
//     closes the span (insideConstrainedOut := false, implication vacuously
//     true, currentConstrainedOut := []) or is a no-op. ✓
//
//   Phase 3/5c/7 (CloseSpanWithinBudget): library postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   Phase 4 (UnconstrainedStep + RenderedEndsWith): insideConstrainedOut stays
//     false until RenderedEndsWith("<<"); EnterObservedConstrainedSpan sets
//     currentConstrainedOut := [] (valid). ✓
//
//   Phase 6 (OpenConstrainedSpan): sets currentConstrainedOut := [] (valid). ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: UnconstrainedChunk postcondition |generatedOut| <= |generated_old|
//     + su; steps += su. EnterObservedConstrainedSpan adds 0 tokens, 0 steps. ✓
//   Phase 2a: Each iteration: ConstrainedStep +1 step, AppendConstrainedToken
//     +1 token (EOS: +1 step, 0 tokens). ✓
//   Phase 2b: CloseSpanIfComplete closed → +1 step, +1 token (">>"). Not
//     closed → ConstrainedStep +1 step, AppendConstrainedToken +1 token
//     (EOS: +1 step, 0 tokens). ✓
//   Phase 3/5c/7: CloseSpanWithinBudget postcondition |generatedOut| <=
//     |generated_old| + budget; steps += budget. ✓
//   Phase 4: UnconstrainedStep +1 step, generated grows by ≤1. ✓
//   Phase 6 (OpenConstrainedSpan): +1 step, +"<<" (1 token). ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the end write: The answer is EXPR. Rules for EXPR: use the EXACT variable names from the problem WITHOUT curly braces (write n1 not {n1}, write frac_1 not {frac_1}), use only +, -, *, /, (, ), int(). Use int() when dividing or multiplying by fractions. Write a single concise expression without repeated terms. Good examples: n * price - discount, int(n1 * frac_1 * frac_2), first_hour_cost + (end_time - start_time - free_hours - 1) * multiplier * first_hour_cost.");

var steps: nat := 0;
var hasCompletedSpan: bool := false;

var phase1Limit: nat := (maxSteps * 70) / 100;
if phase1Limit == 0 && maxSteps > 0 { phase1Limit := 1; }

// ── Phase 1: Free generation in chunks watching for "<<" ──────────────────
while steps < phase1Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var actualChunk: nat := 40;
  if steps + actualChunk > phase1Limit { actualChunk := phase1Limit - steps; }
  if actualChunk == 0 { break; }
  var cg, soo, soe, su := helpers.UnconstrainedChunk(lm, prompt, generated, actualChunk, "<<", eosToken);
  generated := cg;
  steps := steps + su;
  if soe { break; }
  if soo {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg; insideConstrainedOut := ei; currentConstrainedOut := ec;
  }
}

// ── Phase 2a: 4-token warmup (ConstrainedStep, no CloseSpanIfComplete) ────
var warmup1: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && warmup1 < 4
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant warmup1 <= 4
  decreases 4 - warmup1
{
  var cp1 := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next1 := helpers.ConstrainedStep(lm, parser, cp1, currentConstrainedOut, eosToken);
  steps := steps + 1;
  warmup1 := warmup1 + 1;
  if next1 == eosToken { break; }
  var ag1, ai1, ac1 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next1);
  generated := ag1; insideConstrainedOut := ai1; currentConstrainedOut := ac1;
}

// ── Phase 2b: Main constrained loop: CloseSpanIfComplete + ConstrainedStep ──
var inner1: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && inner1 < 30
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + 30 - inner1
{
  var cg1, ci1, cc1, closed1 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed1 {
    generated := cg1; insideConstrainedOut := ci1; currentConstrainedOut := cc1;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var cp1b := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nxt1 := helpers.ConstrainedStep(lm, parser, cp1b, currentConstrainedOut, eosToken);
    steps := steps + 1;
    inner1 := inner1 + 1;
    if nxt1 == eosToken { break; }
    var ag1b, ai1b, ac1b := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt1);
    generated := ag1b; insideConstrainedOut := ai1b; currentConstrainedOut := ac1b;
  }
}

// ── Phase 3: CloseSpanWithinBudget with ALL remaining budget ──────────────
if insideConstrainedOut && steps < maxSteps {
  var bud1 := maxSteps - steps;
  var wg1, wi1, wc1 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud1);
  generated := wg1; insideConstrainedOut := wi1; currentConstrainedOut := wc1;
  steps := steps + bud1;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// ── Phase 4: Fallback free gen (up to 80 more steps) watching for "<<" ───
var phase4Limit: nat := steps + 80;
if phase4Limit > maxSteps { phase4Limit := maxSteps; }
while steps < phase4Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase4Limit - steps
{
  var nxt4 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if nxt4 == eosToken { break; }
  generated := generated + [nxt4];
  if RenderedEndsWith(generated, "<<") {
    var eg4, ei4, ec4 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg4; insideConstrainedOut := ei4; currentConstrainedOut := ec4;
  }
}

// ── Phase 5a: Warmup for second span ─────────────────────────────────────
var warmup2: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && warmup2 < 4
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant warmup2 <= 4
  decreases 4 - warmup2
{
  var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
  var nxt2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
  steps := steps + 1;
  warmup2 := warmup2 + 1;
  if nxt2 == eosToken { break; }
  var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt2);
  generated := ag2; insideConstrainedOut := ai2; currentConstrainedOut := ac2;
}

// ── Phase 5b: Main constrained loop for second span ──────────────────────
var inner2: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && inner2 < 30
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + 30 - inner2
{
  var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed2 {
    generated := cg2; insideConstrainedOut := ci2; currentConstrainedOut := cc2;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var cp2b := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nxt2b := helpers.ConstrainedStep(lm, parser, cp2b, currentConstrainedOut, eosToken);
    steps := steps + 1;
    inner2 := inner2 + 1;
    if nxt2b == eosToken { break; }
    var ag2b, ai2b, ac2b := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt2b);
    generated := ag2b; insideConstrainedOut := ai2b; currentConstrainedOut := ac2b;
  }
}

// ── Phase 5c: CloseSpanWithinBudget for second span ──────────────────────
if insideConstrainedOut && steps < maxSteps {
  var bud2 := maxSteps - steps;
  if bud2 > 120 { bud2 := 120; }
  var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud2);
  generated := wg2; insideConstrainedOut := wi2; currentConstrainedOut := wc2;
  steps := steps + bud2;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// ── Phase 6: Force open a span if nothing completed yet ───────────────────
if !insideConstrainedOut && !hasCompletedSpan && steps + 2 <= maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg; insideConstrainedOut := fi; currentConstrainedOut := fc;
  steps := steps + 1;

  // Warmup 4 tokens for forced span
  var warmup3: nat := 0;
  while insideConstrainedOut && steps < maxSteps && warmup3 < 4
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    invariant warmup3 <= 4
    decreases 4 - warmup3
  {
    var cp3 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nxt3 := helpers.ConstrainedStep(lm, parser, cp3, currentConstrainedOut, eosToken);
    steps := steps + 1;
    warmup3 := warmup3 + 1;
    if nxt3 == eosToken { break; }
    var ag3, ai3, ac3 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt3);
    generated := ag3; insideConstrainedOut := ai3; currentConstrainedOut := ac3;
  }

  // Main loop for forced span
  var inner3: nat := 0;
  while insideConstrainedOut && steps < maxSteps && inner3 < 25
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps + 25 - inner3
  {
    var cg3, ci3, cc3, closed3 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed3 {
      generated := cg3; insideConstrainedOut := ci3; currentConstrainedOut := cc3;
      steps := steps + 1;
      hasCompletedSpan := true;
    } else {
      var cp3b := prompt + generated[..|generated| - |currentConstrainedOut|];
      var nxt3b := helpers.ConstrainedStep(lm, parser, cp3b, currentConstrainedOut, eosToken);
      steps := steps + 1;
      inner3 := inner3 + 1;
      if nxt3b == eosToken { break; }
      var ag3b, ai3b, ac3b := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt3b);
      generated := ag3b; insideConstrainedOut := ai3b; currentConstrainedOut := ac3b;
    }
  }

  // Close with ALL remaining budget for forced span
  if insideConstrainedOut && steps < maxSteps {
    var bud3 := maxSteps - steps;
    var wg3, wi3, wc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud3);
    generated := wg3; insideConstrainedOut := wi3; currentConstrainedOut := wc3;
    steps := steps + bud3;
  }
}

// ── Phase 7: Final safety close ───────────────────────────────────────────
if insideConstrainedOut && steps < maxSteps {
  var bud4 := maxSteps - steps;
  if bud4 > 0 {
    var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud4);
    generated := wg4; insideConstrainedOut := wi4; currentConstrainedOut := wc4;
    steps := steps + bud4;
  }
}

cost := steps;
